// Convertit le brouillon validé (Markdown) en HTML pour une note de travail ServiceNow :
// titres, gras, italique, code, listes à puces et numérotées, tableaux.
// Le HTML est encadré par [code]…[/code], la balise qui permet à ServiceNow d'afficher
// du HTML dans le journal. La mention « Statut : brouillon… » est retirée.

const echapper = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function enLigne(texte) {
  return echapper(texte)
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*([^*\s][^*]*)\*/g, '<em>$1</em>')
    .replace(/(^|[\s(])_([^_\s][^_]*)_(?=$|[\s.,;:!?)])/g, '$1<em>$2</em>');
}

const cellules = (ligne) => ligne.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
const estSeparateur = (ligne) => /^\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?$/.test(ligne.trim());
const CELLULE = 'border:1px solid #c9ccd1;padding:4px 8px;text-align:left;vertical-align:top';

function versHtml(markdown) {
  const lignes = String(markdown || '')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .filter((l) => !/^\s*\**\s*Statut\s*:\s*brouillon/i.test(l));
  const blocs = [];
  const puce = /^[-*+]\s+/;
  const numero = /^\d+[.)]\s+/;
  const separation = /^(-{3,}|\*{3,})$/;
  let i = 0;
  while (i < lignes.length) {
    const t = lignes[i].trim();
    if (t === '' || separation.test(t)) { i += 1; continue; }

    const titre = t.match(/^(#{1,6})\s+(.*)$/);
    if (titre) {
      const niveau = Math.min(titre[1].length + 1, 6);
      blocs.push(`<h${niveau}>${enLigne(titre[2])}</h${niveau}>`);
      i += 1;
      continue;
    }

    if (t.startsWith('|')) {
      const rangees = [];
      while (i < lignes.length && lignes[i].trim().startsWith('|')) {
        if (!estSeparateur(lignes[i])) rangees.push(cellules(lignes[i]));
        i += 1;
      }
      const largeur = Math.max(...rangees.map((r) => r.length));
      const html = rangees.map((r, n) => {
        const balise = n === 0 ? 'th' : 'td';
        const cases = Array.from({ length: largeur }, (_, k) => `<${balise} style="${CELLULE}">${enLigne(r[k] || '')}</${balise}>`);
        return `<tr>${cases.join('')}</tr>`;
      });
      blocs.push(`<table style="border-collapse:collapse">${html.join('')}</table>`);
      continue;
    }

    if (puce.test(t) || numero.test(t)) {
      const ordonnee = numero.test(t);
      const motif = ordonnee ? numero : puce;
      const elements = [];
      while (i < lignes.length && motif.test(lignes[i].trim())) {
        elements.push(`<li>${enLigne(lignes[i].trim().replace(motif, ''))}</li>`);
        i += 1;
      }
      const balise = ordonnee ? 'ol' : 'ul';
      blocs.push(`<${balise}>${elements.join('')}</${balise}>`);
      continue;
    }

    // Paragraphe : lignes consécutives réunies, séparées par un retour à la ligne.
    const contenu = [];
    while (i < lignes.length) {
      const l = lignes[i].trim();
      if (l === '' || /^#{1,6}\s/.test(l) || l.startsWith('|') || puce.test(l) || numero.test(l) || separation.test(l)) break;
      contenu.push(enLigne(l));
      i += 1;
    }
    blocs.push(`<p>${contenu.join('<br>')}</p>`);
  }
  return blocs.join('');
}

return $input.all().map((item, i) => {
  const r = item.json;
  const f = r.fields || r;
  const entete = '<p><em>REX validé (relu par un humain avant publication)</em></p>';
  return {
    json: {
      recordId: r.id,
      sysId: f.sys_id,
      noteDeTravail: `[code]${entete}${versHtml(f.Brouillon)}[/code]`,
    },
    pairedItem: { item: i },
  };
});
